import { beforeEach, describe, expect, it, vi } from "vitest";

const query = vi.hoisted(() => ({ from: vi.fn(), order: vi.fn(), select: vi.fn() }));

vi.mock("@/lib/supabase/server", () => ({ createSupabaseServerClient: async () => ({ from: query.from }) }));

import { loadTuitionPeriods } from "@/features/tuition/data";

beforeEach(() => {
  vi.clearAllMocks();
  query.from.mockReturnValue({ select: query.select });
  query.select.mockReturnValue({ order: query.order });
});

describe("tuition period list loader", () => {
  it("maps locked_at and the status, and reports a failed read as null", async () => {
    query.order.mockResolvedValueOnce({
      data: [
        { due_on: null, ends_on: "2026-10-31", id: "oct", locked_at: "2026-09-28T02:40:00Z", name: "Tháng 10", starts_on: "2026-10-01", status: "locked" },
        { due_on: "2026-11-15", ends_on: "2026-11-30", id: "nov", locked_at: null, name: "Tháng 11", starts_on: "2026-11-01", status: "something" },
      ],
      error: null,
    });

    await expect(loadTuitionPeriods()).resolves.toEqual([
      { dueOn: null, endsOn: "2026-10-31", id: "oct", lockedAt: "2026-09-28T02:40:00Z", name: "Tháng 10", startsOn: "2026-10-01", status: "locked" },
      { dueOn: "2026-11-15", endsOn: "2026-11-30", id: "nov", lockedAt: null, name: "Tháng 11", startsOn: "2026-11-01", status: "draft" },
    ]);
    expect(query.from).toHaveBeenCalledWith("tuition_collection_periods");
    expect(String(query.select.mock.calls[0][0])).toMatch(/\blocked_at\b/);
    expect(query.order).toHaveBeenCalledWith("starts_on", { ascending: false });

    query.order.mockResolvedValueOnce({ data: null, error: { message: "boom" } });
    await expect(loadTuitionPeriods()).resolves.toBeNull();
  });
});
